require __DIR__.'/../app/bootstrap.php';require_permission('users.manage');$msg=$err=null;$admin=current_user();
function au_access_row(int $id): ?array {try{$q=db()->prepare("SELECT u.id,u.role,u.status,COALESCE(up.approval_status,'approved') approval_status,up.custom_role_id,sr.name custom_role_name,sr.permissions_json,sr.status custom_role_status FROM users u LEFT JOIN user_profiles up ON up.user_id=u.id LEFT JOIN system_roles sr ON sr.id=up.custom_role_id WHERE u.id=? LIMIT 1");$q->execute([$id]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function au_role_permissions(int $roleId): array {if($roleId<=0)return [];try{$q=db()->prepare("SELECT permissions_json,status FROM system_roles WHERE id=? LIMIT 1");$q->execute([$roleId]);$r=$q->fetch();if(!$r||!(int)$r['status'])throw new RuntimeException('Selected custom role is disabled or missing.');$p=json_decode((string)$r['permissions_json'],true);return is_array($p)?array_values(array_unique(array_intersect(array_keys(permission_registry()),$p))):[];}catch(RuntimeException $e){throw $e;}catch(Throwable $e){throw new RuntimeException('Could not validate the selected custom role.');}}
function au_can_assign_custom_role(int $roleId,array $actor): bool {if($roleId<=0)return true;if(is_super_admin($actor))return true;if(!has_permission('users.assign_staff_role',$actor))return false;$rolePerms=au_role_permissions($roleId);foreach($rolePerms as $perm)if(!has_permission($perm,$actor))return false;return true;}
function au_assert_staff_assignment(string $newRole,int $customRoleId,array $actor,?array $target=null): void {
    $core=core_role_registry();if(!isset($core[$newRole]))throw new RuntimeException('Invalid core role.');
    $currentRole=(string)($target['role']??'user');$currentStaff=!empty($core[$currentRole]['admin_access'])||!empty($target['custom_role_id']);$newStaff=!empty($core[$newRole]['admin_access'])||$customRoleId>0;
    if($target && (int)$target['id']===(int)$actor['id'] && ($newRole!==$currentRole || $customRoleId!==(int)($target['custom_role_id']??0)))throw new RuntimeException('You cannot change your own access role from Users. Ask another authorized administrator.');
    if(($currentStaff||$newStaff)&&!is_super_admin($actor)&&!has_permission('users.assign_staff_role',$actor))throw new RuntimeException('Staff-role assignment permission is required.');
    if(($currentRole==='admin'||$newRole==='admin')&&!is_super_admin($actor)&&!has_permission('users.assign_admin',$actor))throw new RuntimeException('Admin account management permission is required.');
    if($target && $currentRole==='admin'&&empty($target['custom_role_id'])&&!is_super_admin($actor))throw new RuntimeException('Only a Super Admin can modify a Super Admin account.');
    if($customRoleId>0&&!au_can_assign_custom_role($customRoleId,$actor))throw new RuntimeException('You cannot assign a custom role containing permissions above your own access level.');
}
function au_assert_target_action(int $id,array $actor): array {$target=au_access_row($id);if(!$target)throw new RuntimeException('User not found.');if((int)$target['id']===(int)$actor['id'])throw new RuntimeException('Use your Staff Profile to manage your own account. Access/approval changes to your own account are blocked here.');$core=core_role_registry();$staff=!empty($core[$target['role']]['admin_access'])||!empty($target['custom_role_id']);if($staff&&!is_super_admin($actor)&&!has_permission('users.assign_staff_role',$actor))throw new RuntimeException('Staff account management permission is required.');if($target['role']==='admin'&&!is_super_admin($actor)&&!has_permission('users.assign_admin',$actor))throw new RuntimeException('Admin account management permission is required.');if($target['role']==='admin'&&empty($target['custom_role_id'])&&!is_super_admin($actor))throw new RuntimeException('Only a Super Admin can modify a Super Admin account.');return $target;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$action=(string)($_POST['action']??'update');$id=(int)($_POST['id']??0);
 if($action==='create'){$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$phone=trim((string)($_POST['phone']??''));$password=(string)($_POST['password']??'');$role=(string)($_POST['role']??'user');$customRole=(int)($_POST['custom_role_id']??0);au_assert_staff_assignment($role,$customRole,$admin);if(!$name||(!$email&&!$phone)||strlen($password)<max(8,min(64,setting_int('password_min_length',8))))throw new RuntimeException('Name, contact and a valid minimum-length password are required.');$approval=in_array(($_POST['approval_status']??'approved'),['approved','pending','rejected'],true)?$_POST['approval_status']:'approved';$source=in_array(($_POST['approval_source']??'manual'),['manual','auto','package','payment'],true)?$_POST['approval_source']:'manual';db()->beginTransaction();try{db()->prepare("INSERT INTO users(name,email,phone,password_hash,role,status) VALUES(?,?,?,?,?,'active')")->execute([$name,$email?:null,$phone?:null,password_hash($password,PASSWORD_DEFAULT),$role]);$id=(int)db()->lastInsertId();db()->prepare("INSERT INTO user_profiles(user_id,approval_status,approval_source,custom_role_id,package_plan_id,approved_by,approved_at,notes) VALUES(?,?,?,?,?,?,?,?)")->execute([$id,$approval,$source,$customRole?:null,(int)($_POST['package_plan_id']??0)?:null,$admin['id'],$approval==='approved'?date('Y-m-d H:i:s'):null,trim((string)($_POST['notes']??''))]);db()->commit();$msg='User created.';}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
 elseif($action==='approve'){$target=au_assert_target_action($id,$admin);approve_user_account($id,(string)($_POST['approval_source']??'manual'),(int)$admin['id'],(int)($_POST['package_plan_id']??0)?:null,trim((string)($_POST['notes']??'')));$msg='User approved.';}
 elseif($action==='reject'){$target=au_assert_target_action($id,$admin);reject_user_account($id,(int)$admin['id'],trim((string)($_POST['notes']??'')));$msg='User rejected.';}
 else{$target=au_access_row($id);if(!$target)throw new RuntimeException('User not found.');$role=(string)($_POST['role']??$target['role']);$customRole=(int)($_POST['custom_role_id']??0);au_assert_staff_assignment($role,$customRole,$admin,$target);$status=in_array(($_POST['status']??'active'),['active','blocked'],true)?$_POST['status']:'active';if((int)$target['id']===(int)$admin['id']&&$status!==(string)$target['status'])throw new RuntimeException('You cannot change your own account status here.');db()->beginTransaction();try{db()->prepare("UPDATE users SET role=?,status=? WHERE id=?")->execute([$role,$status,$id]);ensure_user_profile_row($id);db()->prepare("UPDATE user_profiles SET custom_role_id=?,notes=? WHERE user_id=?")->execute([$customRole?:null,trim((string)($_POST['notes']??'')),$id]);db()->commit();$msg='User updated.';}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
 }catch(Throwable $e){$err=$e->getMessage();}}
$roles=db()->query("SELECT id,name,permissions_json FROM system_roles WHERE status=1 ORDER BY name")->fetchAll();$plans=db()->query("SELECT id,name,price FROM subscription_plans WHERE status=1 ORDER BY price")->fetchAll();
$search=trim((string)($_GET['q']??''));$approval=(string)($_GET['approval']??'');$params=[];$where=[];if($search!==''){$where[]="(u.name LIKE ? OR u.email LIKE ? OR u.phone LIKE ?)";for($i=0;$i<3;$i++)$params[]='%'.$search.'%';}if(in_array($approval,['pending','approved','rejected'],true)){$where[]="COALESCE(up.approval_status,'approved')=?";$params[]=$approval;}
$sql="SELECT u.id,u.name,u.email,u.phone,u.role,u.status,u.created_at,COALESCE(up.approval_status,'approved') approval_status,COALESCE(up.approval_source,'auto') approval_source,up.notes,up.custom_role_id,sr.name custom_role_name,sp.name package_name FROM users u LEFT JOIN user_profiles up ON up.user_id=u.id LEFT JOIN system_roles sr ON sr.id=up.custom_role_id LEFT JOIN subscription_plans sp ON sp.id=up.package_plan_id";if($where)$sql.=" WHERE ".implode(" AND ",$where);$sql.=" ORDER BY u.id DESC LIMIT 400";$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
$stats=db()->query("SELECT COUNT(*) total,SUM(COALESCE(up.approval_status,'approved')='pending') pending_count,SUM(COALESCE(up.approval_status,'approved')='approved') approved_count,SUM(u.role='shopkeeper') shopkeepers,SUM(u.role='blogger') bloggers,SUM(u.role='editor') editors FROM users u LEFT JOIN user_profiles up ON up.user_id=u.id")->fetch();$core=core_role_registry();
