e="approval_source" value="manual"><button class="btn success">Approve</button></form><?php endif;?> <?php if($r['approval_status']!=='rejected'):?><form method="post" style="display:inline"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reject"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="btn danger">Reject</button></form><?php endif;?><?php endif;?></td></tr><?php endforeach;?></table></div></div></div></div>
